// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/books.ts, then fixed by hand where it says so.
// Books, found in ruins. Each has a subject (item.tag, from a hash of its id):
// most teach a skill (a level's worth of practice to whoever reads it), and
// some teach the colony something new (state.knowledge), which some recipes
// need (crafting.ts). A survivor with nothing to do reads the nearest free
// book for READ_TICKS; a job turning up interrupts them (they come back to it).
// A book is used up once read.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Books
{

    public static readonly JsRecord<string> KNOWLEDGE = new() { ["gunsmithing"] = "hand-loading ammo and making guns", ["tailoring"] = "sewing padded armour" };

    public static readonly List<string> SKILL_BOOKS = ["build", "farm", "craft", "cook", "doctor", "guard"];

    /// <summary>One book in this many is about something new rather than a skill.</summary>
    public const int KNOWLEDGE_BOOK_ONE_IN = 4;

    public const int READ_TICKS = 300;

    /// <summary>A book's subject, from its id.</summary>
    public static string bookSubject(string id)
    {
        var roll = Hash.hashRoll(Hash.idNumber(id), 0xb00c);
        if (roll < ((double)(1) / (KNOWLEDGE_BOOK_ONE_IN)))
        {
            return Js.NN((Js.ObjectKeys(KNOWLEDGE))[Js.Idx(JsMath.floor((roll * KNOWLEDGE_BOOK_ONE_IN) * 2) % 2)]);
        }
        return Js.NN(SKILL_BOOKS[Js.Idx(JsMath.floor(roll * 1000) % SKILL_BOOKS.length)]);
    }

    public static bool knows(SimState state, string k)
    {
        return state.knowledge.includes(k);
    }

    /// <summary>"a book on farming", "a book on gunsmithing".</summary>
    public static string describeBook(Item item)
    {
        return $"a book on {Js.Str(item.tag ?? "nothing much")}";
    }

    /// <summary>Idle with nothing to do: go and read a free book. Returns true if they set off.</summary>
    public static bool startReading(SimState state, Survivor s)
    {
        if (Js.T(s.reading) || Js.T(s.breakdown))
        {
            return false;
        }
        var book = Needs.nearestFreeItem(state, s, "book");
        if (!Js.T(Js.T(book?.pos)))
        {
            return false;
        }
        book.reservedBy = s.id;
        s.reading = new() { itemId = book.id, progress = 0 };
        s.note = $"going to read {Js.Str(describeBook(book))}";
        return true;
    }

    /// <summary>Runs when standing still, with leisure. Returns true if reading handled this tick.</summary>
    public static bool updateReading(SimState state, Survivor s)
    {
        if (!Js.T(s.reading))
        {
            return false;
        }
        if (state.tick >= s.nextSeekTick)
        {
            s.nextSeekTick = state.tick + Jobs.IDLE_RETRY_TICKS;
            var was = s.reading;
            stopReading(state, s, "put the book down for work");
            if (Js.T(JobChoice.seekJob(state, s)))
            {
                return true;
            }
            var book_1 = Items.getItem(state, was.itemId);
            if (Js.T(Js.T(book_1?.pos)) && (book_1.reservedBy == null))
            {
                book_1.reservedBy = s.id;
                s.reading = was;
            }
            else
            {
                return false;
            }
        }
        var book = Items.getItem(state, s.reading.itemId);
        if (!Js.T(Js.T(book?.pos)) || (book.reservedBy != s.id))
        {
            stopReading(state, s, "book gone");
            return false;
        }
        if (!Js.T(Space.samePoint(s.pos, book.pos)))
        {
            var path = Pathfinding.findPathToAny(state.grid, s.pos, [book.pos]);
            if (!Js.T(path) || (path.length == 0))
            {
                stopReading(state, s, "can't reach the book");
                return false;
            }
            Survivors.walk(s, path, state.walkabilityVersion);
            return true;
        }
        s.reading.progress += 1;
        if (s.reading.progress == 1)
        {
            s.note = $"reading {Js.Str(describeBook(book))}";
        }
        if (s.reading.progress < READ_TICKS)
        {
            return true;
        }
        s.reading = null;
        Items.removeItem(state, book);
        learn(state, s, book.tag ?? "");
        return true;
    }

    public static void learn(SimState state, Survivor s, string subject)
    {
        if (/*TODO in*/Js.In(subject, KNOWLEDGE))
        {
            var k = subject;
            if (!Js.T(knows(state, k)))
            {
                state.knowledge.push(k);
            }
            s.note = $"learned {Js.Str(k)}";
            Events.logEvent(state, $"{Js.Str(s.name)} read up on {Js.Str(k)}: the colony can now get on with {Js.Str(KNOWLEDGE[Js.Idx(k)])}");
            return;
        }
        var type = subject;
        s.xp[Js.Idx(type)] = (Js.Q(s.xp[Js.Idx(type)], 0)) + Skills.XP_PER_LEVEL;
        s.note = $"read a book on {Js.Str(type)}";
    }

    /// <summary>Puts the book back (unreserved). Safe to call when not reading.</summary>
    public static void stopReading(SimState state, Survivor s, string note)
    {
        if (!Js.T(s.reading))
        {
            return;
        }
        var book = Items.getItem(state, s.reading.itemId);
        if (Js.T(book) && (book.reservedBy == s.id))
        {
            book.reservedBy = null;
        }
        s.reading = null;
        s.goal = null;
        s.path = [];
        s.pathVersion = -1;
        s.note = note;
    }
}
